tools.roman_to_int:
def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    prev = 0
    for c in reversed(s):
        curr = values[c]
        if curr < prev:
            result -= curr
        else:
            result += curr
        prev = curr
    return result

